<!DOCTYPE html><html lang="en" data-theme="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>404 - Page Not Found</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
<link href="/public/css/app.css" rel="stylesheet"><style>.error-page{min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;background:var(--bg-primary)}.error-code{font-size:8rem;font-weight:700;background:linear-gradient(135deg,#6366f1,#8b5cf6);-webkit-background-clip:text;-webkit-text-fill-color:transparent;line-height:1}</style>
</head><body><div class="error-page"><div><div class="error-code">404</div><h2 style="color:var(--text-primary)">Page Not Found</h2><p style="color:var(--text-secondary);max-width:400px;margin:1rem auto">The page you're looking for doesn't exist or has been moved.</p><a href="/dashboard" class="btn btn-primary btn-lg mt-3"><i class="bi bi-arrow-left"></i> Back to Dashboard</a></div></div></body></html>
